const products=[
{id:'home',category:'research',label:'THE SIGNATURE PACKAGE',title:'The Home Story Package',short:'Your home’s story, thoughtfully researched, written and gathered in one place.',copy:'A sourced narrative that connects your home to the families, records and neighborhood around it. We begin with what you know and follow the evidence, keeping unanswered questions visible.',items:['A written home history with source references','Family and ownership research where records allow','Historic maps, records and photographs as available','A guest and family FAQ and a one-page story flyer','An organized digital records packet and owner-folder checklist'],art:'paper',artTitle:'The Home<br>Story'},
{id:'family',category:'research',label:'FAMILY VOICES',title:'Family Story Recording',short:'Memories in their own words. A record for the people who come next.',copy:'A thoughtful conversation to preserve the stories your family wishes to share. You decide what is recorded, what stays private and what may be carried forward.',items:['A conversation about your recording goals','Family memories recorded with permission','Sharing boundaries agreed with participants','A keepsake recording in the agreed format'],art:'voice'},
{id:'site',category:'research',label:'DOCUMENT & PRESERVE',title:'Preservation Record',short:'Bring together the details that help document a historic home.',copy:'Research and owner collaboration to help prepare a Florida Master Site File form for submission. Documentation gives a home a fuller record; submission itself does not establish historic designation or protection.',items:['Review of available property documentation','An organized record of relevant findings','Help preparing the site-file form with the owner','Unresolved questions clearly identified'],art:'paper',artTitle:'A Record<br>of Home'},
{id:'print',category:'keepsakes',label:'HISTORY TO KEEP',title:'Framed Home History',short:'A carefully written piece of your home’s story, made for the wall.',copy:'A framed history print drawn from an agreed, sourced narrative. A quiet reminder of the people and place behind a home.',items:['A concise home-history narrative','Layout drawn from the Root & Simmer visual family','Your review of the story before production','Print size, framing and delivery agreed in advance'],art:'print',artTitle:'A Place<br>Called Home'},
{id:'copies',category:'keepsakes',label:'SHARE THE STORY',title:'Printed Story Copies',short:'Keep a copy close. Share one with family or the next caretaker.',copy:'Printed copies of your completed history packet, prepared to the format and quantity you need. Printing is arranged after the content and production details are agreed.',items:['Copies of an approved, completed packet','Quantity and print format of your choice','Production cost confirmed before printing'],art:'paper',artTitle:'Carry History<br>Forward'},
{id:'card',category:'welcome',label:'RESPECT THE ROOTS',title:'Guest History Card',short:'A warm introduction to the home, the neighborhood and its living history.',copy:'A concise, sourced introduction that helps guests discover Lincolnville’s roots and appreciate the community they are visiting.',items:['A short introduction to the home’s documented story','Neighborhood context and respectful guest guidance','A clear card layout for print or digital sharing'],art:'guide',artTitle:'Welcome<br>to the Roots'},
{id:'map',category:'keepsakes',label:'SELF-GUIDED DISCOVERY',title:'Neighborhood Story Map',short:'Follow the ground beneath your feet, with context and care.',copy:'A printed map and neighborhood narrative developed from verified research. The scope and stops are agreed together, with care for residents’ privacy and daily life.',items:['A self-guided map with agreed streets and stops','Short narratives with source references','Respectful wayfinding and visitor guidance','A print-ready layout'],art:'guide',artTitle:'Follow<br>the Story'},
{id:'welcome',category:'welcome',label:'HOSPITALITY WITH APPRECIATION',title:'Readiness & Welcome',short:'Thoughtful details that help a guest arrive with appreciation.',copy:'A personal hospitality service supporting a respectful arrival and a deeper connection to Lincolnville.',items:['Readiness checks within an agreed scope','Local wayfinding and neighborhood guidance','Respect Thy Neighbor information','A welcome shaped around the home and community'],art:'guide',artTitle:'Welcome<br>In'}
];
let bag={};try{const saved=JSON.parse(localStorage.getItem('rs-selections')||'{}');for(const p of products){if(Number.isInteger(saved[p.id])&&saved[p.id]>0&&saved[p.id]<=20)bag[p.id]=saved[p.id]}}catch{}
const $=s=>document.querySelector(s);const $$=s=>document.querySelectorAll(s);let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function art(p){if(p.art==='voice')return '<div class="voice-mark" aria-hidden="true">'+[20,37,53,30,65,45,28,50,64,34,20].map(h=>`<i style="--h:${h}px"></i>`).join('')+'</div>';return `<div aria-hidden="true" class="mini-paper ${p.art==='print'?'frame':''}"><b>${p.artTitle}</b><i></i><i></i><i></i></div>`}
function render(filter='all'){$('#products').innerHTML=products.filter(p=>filter==='all'||p.category===filter).map(p=>`<article class="product"><div class="product-art ${p.art}">${art(p)}</div><div class="product-body"><span class="eyebrow">${p.label}</span><h3>${p.title}</h3><p>${p.short}</p><div class="product-bottom"><button data-details="${p.id}" aria-label="Details about ${p.title}">View details ↗</button><button class="add" data-add="${p.id}" aria-label="Add ${p.title} to your inquiry">Select +</button></div></div></article>`).join('')}
function update(){const count=Object.values(bag).reduce((a,b)=>a+b,0);$('#count').textContent=count;$('#bag-button').setAttribute('aria-label',`Open selected services, ${count} selected`);try{localStorage.setItem('rs-selections',JSON.stringify(bag))}catch{};renderBag()}
function add(id){bag[id]=Math.min((bag[id]||0)+1,20);update();toast('Added to your inquiry. Review in Your selections.')}function renderBag(){const chosen=products.filter(p=>bag[p.id]);$('#bag-items').innerHTML=chosen.length?chosen.map(p=>`<div class="bag-item"><div><h3>${p.title}</h3><label>Quantity <input type="number" min="1" max="20" value="${bag[p.id]}" data-qty="${p.id}" aria-label="Quantity for ${p.title}"></label></div><button class="remove" data-remove="${p.id}" aria-label="Remove ${p.title}">Remove</button></div>`).join(''):'<p>Your inquiry is waiting for its first story.</p><button class="button" id="browse">Browse our work →</button>';$('#quote-content').hidden=!chosen.length}
$('#filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render(b.dataset.filter)});
document.addEventListener('click',e=>{const a=e.target.closest('[data-add]');if(a)add(a.dataset.add);const v=e.target.closest('[data-details]');if(v){const p=products.find(x=>x.id===v.dataset.details);$('#detail-category').textContent=p.label;$('#detail-title').textContent=p.title;$('#detail-copy').textContent=p.copy;$('#detail-list').innerHTML=p.items.map(x=>`<li>${x}</li>`).join('');$('#detail-add').dataset.id=p.id;$('#product-dialog').showModal()}const rem=e.target.closest('[data-remove]');if(rem){delete bag[rem.dataset.remove];update()}if(e.target.closest('[data-close]'))e.target.closest('dialog').close();if(e.target.id==='browse'){$('#bag-dialog').close();location.hash='work'}});
$('#detail-add').onclick=()=>{add($('#detail-add').dataset.id);$('#product-dialog').close()};$('#bag-button').onclick=()=>{renderBag();$('#bag-dialog').showModal()};$('#bag-items').addEventListener('change',e=>{if(e.target.dataset.qty){bag[e.target.dataset.qty]=Math.max(1,Math.min(20,parseInt(e.target.value)||1));update()}});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function email(form,subject,body){const link='mailto:rootnsimmer@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);window.location.href=link;form.querySelector('.form-status').textContent='Your email draft is ready to open. Review and send it in your email app. If it does not open, email rootnsimmer@gmail.com directly.'}
$('#join-form').onsubmit=e=>{e.preventDefault();const f=e.target,d=new FormData(f);email(f,'Lincolnville Connection — introduction',`Hello Kimberly,\n\nI would like to hear about Lincolnville Connection.\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nMy connection: ${d.get('connection')}\n\nPlease contact me about the community.`)};
$('#records-form').onsubmit=e=>{e.preventDefault();const f=e.target,d=new FormData(f);email(f,'Lincolnville records request',`Hello Kimberly,\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nI am a: ${d.get('role')}\nLooking for: ${d.get('topic')}\nAddress or family name: ${d.get('subject')}\n\nWhat I know:\n${d.get('details')}\n\nPlease reply about this request. Public sharing of family material would require separate permission.`)};
$('#quote-form').onsubmit=e=>{e.preventDefault();const f=e.target,d=new FormData(f);const lines=products.filter(p=>bag[p.id]).map(p=>`${bag[p.id]} × ${p.title}`).join('\n');email(f,'Root & Simmer — service quote request',`Hello Kimberly,\n\nI would like to discuss these offerings:\n${lines}\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\n\nAbout my project:\n${d.get('details')}\n\nI understand scope and fees will be agreed before work begins.`)};
render();update();
